function split(total, people, tipPct, taxPct){
  total = Number(total)||0; people = Math.max(1, Math.floor(people)||1);
  tipPct = Number(tipPct)||0; taxPct = Number(taxPct)||0;
  var tax = total * taxPct/100;
  var subtotal = total + tax;
  var tip = subtotal * tipPct/100;
  var grand = subtotal + tip;
  var per = grand / people;
  return { tax: tax, tip: tip, grand: grand, per: per, people: people };
}
var EXPORTS={split:split};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
